function statsTable(games,teams,{advanced=false,pointsThreshold=0,huckDistance=huckYards,outlierHighlight=false,breakdownTable=null,matchupGaps={},unknownPlayers={}}={}){
 const settings=secondaryEdgeSettings(),onOffColumns=breakdownTable==='season'?[['holdRatePlusMinus','Adjusted hold +/-'],['opponentHoldRatePlusMinus','Adjusted opp hold +/-']]:[],cols=advanced?[...STAT_COLUMNS,['huckCompletionRate','Huck completion rate'],['plusMinus','+/-'],['throwingEdge','Throw EDGE'],['receivingEdge','Receive EDGE'],['secondaryThrowingEdge','Secondary throwing EDGE'],['totalEdge','Total EDGE'],['totalEdgePerPoint','Total EDGE/pt'],['totalEdgePerTouch','Total EDGE/touch'],['throwEdgeAllowed','Throw EDGE allowed'],['receiveEdgeAllowed','Receive EDGE allowed'],['edgeAllowed','EDGE allowed'],['edgeAllowedPerPoint','EDGE allowed/pt'],['opponentScoredRate','Opp scored %'],['opponentScoredRateFromD','Opp scored % (D start)'],['opponentScoredRateFromO','Opp scored % (O start)'],...onOffColumns]:STAT_COLUMNS;
 const rows=(advanced?(games.length===0?statsFor(teams,games,huckDistance).map(r=>({...r,plusMinus:0,throwingEdge:0,receivingEdge:0,secondaryThrowingEdge:0,totalEdge:0,totalEdgePerPoint:0,totalEdgePerTouch:0,throwEdgeAllowed:0,receiveEdgeAllowed:0,edgeAllowed:0,edgeAllowedPerPoint:0,opponentScoredRate:0,opponentScoredRateFromD:0,opponentScoredRateFromO:0})):games.length===1?advancedStatsFor(games[0],teams[0],gameOse(games[0],teams[0]),settings.previousShare,settings.previousPreviousShare,settings.includeInTotal,huckDistance).rows:seasonAdvancedForTeams(games,teams,huckDistance)):statsFor(teams,games,huckDistance)).filter(row=>row.points>pointsThreshold);
 if(onOffColumns.length){const models=new Map(teams.map(t=>[t.id,teamAdjusted(games,t)]));for(const row of rows){const playerTeam=teams.find(t=>t.players.some(p=>p.id===row.id)),entry=models.get(playerTeam?.id);Object.assign(row,{holdRatePlusMinus:entry?.result?.hold.ratings[row.id]?.value??null,opponentHoldRatePlusMinus:entry?.result?.opponentHold.ratings[row.id]?.value??null,adjustedEntry:entry});}}
 const deviations=Object.fromEntries(cols.map(([key])=>{const values=rows.filter(row=>row[key]!==null).map(row=>Number(row[key])||0),mean=values.reduce((sum,value)=>sum+value,0)/(values.length||1),stdev=Math.sqrt(values.reduce((sum,value)=>sum+(value-mean)**2,0)/(values.length||1));return [key,{mean,stdev}];}));
 const outlier=(key,value)=>{if(!outlierHighlight||value===null)return '';const d=deviations[key];if(!d?.stdev)return '';const z=(Number(value)-d.mean)/d.stdev,direction=z>1?'high':z<-1?'low':'';if(!direction)return '';const magnitude=Math.abs(z);return `outlier-${direction}${magnitude>=4?' outlier-tier4':magnitude>=3?' outlier-tier3':magnitude>=2?' outlier-border':''}`;},outlierTitle=(key,value)=>{if(!outlierHighlight||value===null)return '';const d=deviations[key];if(!d?.stdev)return '';const z=(Number(value)-d.mean)/d.stdev;if(Math.abs(z)<=1)return '';return ` data-outlier-tooltip="${esc(`${z>=0?'+':''}${z.toFixed(2)} standard deviations from the column mean`)}"`;};
 const defenseIncomplete=games.some(g=>g.source?.defenseAvailable===false),edgeKeys=['throwingEdge','receivingEdge','secondaryThrowingEdge','totalEdge','throwEdgeAllowed','receiveEdgeAllowed','edgeAllowed'],ratioKeys=['totalEdgePerPoint','edgeAllowedPerPoint','totalEdgePerTouch'],opponentScoredDenominators={opponentScoredRate:'defenseOpportunities',opponentScoredRateFromD:'defenseOpportunitiesFromD',opponentScoredRateFromO:'defenseOpportunitiesFromO'},display=(key,value,row)=>onOffColumns.some(([onOffKey])=>onOffKey===key)?(row.adjustedEntry?adjustedCell(row.adjustedEntry,key==='holdRatePlusMinus'?'hold':'opponentHold',row.id):'—'):ratioKeys.includes(key)?fixedFmt(value,3):edgeKeys.includes(key)?fixedFmt(value,2):key in opponentScoredDenominators?fixedFmt(value*100,1)+'% ('+fmt(row[opponentScoredDenominators[key]])+')':key==='huckCompletionRate'?fixedFmt(value*100,1)+'%':fmt(value),header=label=>label.includes(' ')?label.replace(/ (?!.* )/,'<br>'):label,sorted=[...rows].sort((a,b)=>{const av=statsSort==='name'?a.name.toLowerCase():Number(a[statsSort]||0),bv=statsSort==='name'?b.name.toLowerCase():Number(b[statsSort]||0);return (av>bv?1:av<bv?-1:0)*(statsDesc?-1:1);});
 return `<div class="card table-scroll"><table class="stats-table"><thead><tr><th><button class="table-sort" data-sort="name">Player ${statsSort==='name'?(statsDesc?'↓':'↑'):''}</button></th>${cols.map(([key,label])=>`<th title="${esc(key)}"><button class="table-sort" data-sort="${key}">${header(label)}${statsSort===key?(statsDesc?' ↓':' ↑'):''}${defenseIncomplete&&['throwAllowed','receiveAllowed','goalsAllowed','assistsAllowed','targets','forcedThrowaways'].includes(key)?'*':''}</button></th>`).join('')}</tr></thead><tbody>${sorted.map(r=>`<tr><td class="stat-name${genderClass(r)}${matchupGaps[r.id]?' matchup-gap':''}${unknownPlayers[r.id]?' unknown-matchup':''}"${breakdownTable?` data-breakdown="${esc(r.id)}" data-breakdown-table="${breakdownTable}"${matchupGaps[r.id]?` data-matchup-gap="${esc(matchupGaps[r.id].join('\n'))}"`:' title="Show matchups"'}`:''}><small>${esc(r.number||'—')}</small>${esc(r.name)}</td>${cols.map(([k])=>`<td class="${outlier(k,r[k])}"${outlierTitle(k,r[k])}${onOffColumns.some(([onOffKey])=>onOffKey===k)?` data-breakdown="${esc(r.id)}" data-breakdown-table="season" data-adjusted-job="${r.adjustedEntry?.id||''}" data-adjusted-side="${k==='holdRatePlusMinus'?'hold':'opponentHold'}" data-adjusted-value="${r[k]??''}"`:''}>${display(k,r[k],r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="stats-help">Click any column heading to sort. All distances in yards.${onOffColumns.length?' Adjusted +/- values are exploratory estimates in percentage points; higher hold and lower opponent hold are better. Click a value or player name for 95% intervals, coverage, prior sensitivity and whole-game validation. † Lineups do not fully separate this player’s effect. A dash means no eligible estimate; … means calculating.':''} Secondary throwing EDGE uses the Player Stats weights; Total EDGE follows the Player Stats inclusion setting. EDGE allowed/pt only counts defensive points where an opponent throw had a named marker or receiver defender (not Unguarded or Unknown); D opp counts all defensive points.</p>`;
}
function statsPage(){const gs=relevantGames(true),ts=team()?[team()]:data.teams,settings=secondaryEdgeSettings();return `<div class="page-heading"><div><p class="eyebrow">From every play to the bigger picture</p><h1>Player statistics</h1><p class="subtext">${new Set(gs.map(g=>g.id)).size} selected games · Recalculated from your play-by-play.</p></div><div class="actions">${teamFilter()}${gameSelectionButton()}<label class="points-filter">Over <input id="player-min-points" type="number" min="0" step="1" value="${minPoints}" aria-label="Minimum points played"> points</label><label class="inline-check outlier-toggle"><input id="outlier-highlight" type="checkbox" ${highlightOutliers?'checked':''}> Highlight outliers</label></div></div><div class="stats-settings edge-settings card"><div><strong>Secondary throwing EDGE</strong><small>Previous thrower · thrower before that</small></div><div class="edge-weights"><input id="secondary-prev" type="number" min="0" max="1" step="0.01" value="${settings.previousShare}" aria-label="Previous thrower weight"><input id="secondary-prev2" type="number" min="0" max="1" step="0.01" value="${settings.previousPreviousShare}" aria-label="Thrower before that weight"></div><label class="inline-check edge-total-check"><input id="include-secondary-total" type="checkbox" ${settings.includeInTotal?'checked':''}> Include in Total EDGE</label><label class="points-filter huck-stats-filter">Huck over <input id="stats-huck-yards" type="number" min="0" step="1" value="${huckYards}" aria-label="Huck distance"> yd</label><button class="primary" id="save-secondary-settings">Update Player Stats</button></div>${statsTable(gs,ts,{advanced:true,pointsThreshold:minPoints,huckDistance:huckYards,outlierHighlight:highlightOutliers,breakdownTable:'season'})}`;}
function gameOse(g,t){if(g?.settings?.ose!=null)return Number(g.settings.ose);return t?.name==='Mischief 2026'?offensiveScoringEfficiency(gamesForTeam(data,t.id),t.id):.56;}
function pointScoreLabel(points,index){const score=[0,0];for(let i=0;i<index;i++){if(points[i].winner==='us')score[0]++;if(points[i].winner==='them')score[1]++;}return `${score[0]}-${score[1]}`;}
function possessionHeatmap(teamId){const t=data.teams.find(x=>x.id===teamId),cells=Array.from({length:112},()=>({touch:0,goal:0}));for(const g of gamesForTeam(data,teamId))for(const p of pointsOf(g)){let touches=[];for(const e of p.events){if(e.type==='possession_start'&&e.side==='us')touches.push(e.location);if(e.type==='pass'&&e.side==='us'&&['complete','goal'].includes(e.outcome))touches.push(e.to);if(e.type==='pass'&&e.side==='us'&&e.outcome==='goal'){for(const pt of touches){const i=Math.min(13,Math.max(0,Math.floor(pt.x/5))),j=Math.min(7,Math.max(0,Math.floor(pt.y/5)));cells[j*14+i].touch++;cells[j*14+i].goal++;}touches=[];}if(e.type==='pass'&&e.side==='us'&&!['complete','goal'].includes(e.outcome)){for(const pt of touches){const i=Math.min(13,Math.max(0,Math.floor(pt.x/5))),j=Math.min(7,Math.max(0,Math.floor(pt.y/5)));cells[j*14+i].touch++;}touches=[];}if(e.type==='turnover'&&e.side==='us'){for(const pt of touches){const i=Math.min(13,Math.max(0,Math.floor(pt.x/5))),j=Math.min(7,Math.max(0,Math.floor(pt.y/5)));cells[j*14+i].touch++;}touches=[];}}for(const pt of touches){const i=Math.min(13,Math.max(0,Math.floor(pt.x/5))),j=Math.min(7,Math.max(0,Math.floor(pt.y/5)));cells[j*14+i].touch++;}}
 const max=Math.max(1,...cells.map(c=>c.touch));modal(`Possession heatmap · ${t?.name||'Team'}`,`<p>Touches are possessions initiated plus completed catches. Hover a box for touches and the share of those touches that ended in a goal.</p><div class="heatmap" style="grid-template-columns:repeat(14,1fr)">${cells.map(c=>{const pct=c.touch?c.goal/c.touch:0;return `<div class="heat-cell" title="${Math.round(pct*100)}% goal rate · ${c.touch} touch${c.touch===1?'':'es'}" style="background:rgba(46,96,74,${c.touch?(.12+.75*c.touch/max):.04})"><span>${c.touch?Math.round(pct*100)+'%':''}</span></div>`;}).join('')}</div>`);}
function possessionHeatmapOriented(teamId){
 const t=data.teams.find(x=>x.id===teamId),rows=18,columns=8,cells=Array.from({length:rows*columns},()=>({touch:0,goal:0}));
 const displayDepth=depth=>depth<=20?depth/2:depth<=90?depth-10:80+(depth-90)/2;
 const add=(point,location,goal)=>{if(!location)return;const depth=point.direction===1?110-location.x:location.x,row=Math.min(rows-1,Math.max(0,Math.floor(displayDepth(depth)/5))),col=Math.min(columns-1,Math.max(0,Math.floor(location.y/5))),cell=cells[row*columns+col];cell.touch++;if(goal)cell.goal++;};
 for(const g of gamesForTeam(data,teamId))for(const point of pointsOf(g)){let touches=[];for(const e of point.events){if(e.type==='possession_start'&&e.side==='us')touches.push(e.location);if(e.type==='pass'&&e.side==='us'&&['complete','goal'].includes(e.outcome))touches.push(e.to);if(e.type==='pass'&&e.side==='us'&&e.outcome==='goal'){touches.forEach(location=>add(point,location,true));touches=[];}else if(e.type==='pass'&&e.side==='us'&&!['complete','goal'].includes(e.outcome)){touches.forEach(location=>add(point,location,false));touches=[];}if(e.type==='turnover'&&e.side==='us'){touches.forEach(location=>add(point,location,false));touches=[];}}touches.forEach(location=>add(point,location,false));}
 const max=Math.max(1,...cells.map(c=>c.touch)),color=(c,mode)=>{if(!c.touch)return '#edf0e8';const value=mode==='touch'?Math.sqrt(c.touch/max):c.goal/c.touch,hue=mode==='touch'?210-195*value:230-225*value,light=mode==='touch'?94-44*value:94-42*value;return `hsl(${hue} 78% ${light}%)`;};
 const grid=(mode)=>`<div class="heatmap heatmap-vertical" style="grid-template-columns:repeat(${columns},1fr)"><div class="heat-endzone-label">End zone</div>${mode==='rate'?'<span class="field-line-label label-brick-top">Brick</span><span class="field-line-label label-midfield">Midfield</span><span class="field-line-label label-brick-bottom">Brick</span>':''}${cells.map((c,i)=>{const row=Math.floor(i/columns);if(row<2)return '';const pct=c.touch?c.goal/c.touch:0,val=mode==='touch'?c.touch:(c.touch?Math.round(pct*100)+'%':'');const cls=[row===16?'heat-endzone-bottom':'',row===5||row===11?'heat-brick':'',row===8?'heat-midfield':'',mode==='rate'&&pct>=.9?'heat-text-light':''].filter(Boolean).join(' ');return `<div class="heat-cell ${cls}" data-heat-detail="${i}" style="background:${color(c,mode)}"><span>${val}</span></div>`;}).join('')}</div>`;
 modal(`Possession heatmaps · ${t?.name||'Team'}`,`<p>Attacking end zone is at the top. Each box is 5×5 yards; the ten-yard end zones are proportionally compressed from the tracked 20-yard end zones.</p><div class="heatmap-pair"><section class="heatmap-panel"><h3>Goal rate by touch</h3>${grid('rate')}</section><section class="heatmap-panel"><h3>Total touches</h3>${grid('touch')}</section></div><p class="heatmap-detail" id="heatmap-detail" aria-live="polite">Click any box to show its touches and goal rate.</p>`);
 $('#modal').querySelectorAll('[data-heat-detail]').forEach(cell=>cell.onclick=()=>{const c=cells[Number(cell.dataset.heatDetail)],pct=c.touch?Math.round(c.goal/c.touch*100):0;$('#heatmap-detail').textContent=`${c.touch} touch${c.touch===1?'':'es'} · ${pct}% of those touches ended in a goal.`;});
}
function dataPage(){return `<div class="page-heading"><div><p class="eyebrow">Your games. Your data.</p><h1>A portable playbook</h1><p class="subtext">Bring your history in. Take every detail with you.</p></div></div><div class="data-grid"><section class="card card-pad"><h2>Import your games</h2><p>Open an existing Statto archive or a Right Trousers JSON export. Teams and new games are merged into this library. Existing games are kept, so repeat imports never duplicate or overwrite your work.</p><div><span class="file-format">.statto</span><span class="file-format">.json</span></div><button class="primary" data-action="import">Choose a file</button></section><section class="card card-pad"><h2>Export your library</h2><p>Share rosters before a tournament, then combine separate scorekeepers’ games afterward. The export contains teams, players, ordered events, and original Statto source records where applicable.</p><div><span class="file-format">JSON · version 1</span></div><button class="primary" data-action="export">Export all data</button></section><section class="card card-pad"><h2>Works at the field</h2><p>Your changes save automatically on this device. After the first visit over HTTPS or localhost, the app can reopen offline. You can add it to your tablet’s home screen from your browser’s menu.</p><p>Export regularly to keep a backup. There is no cloud account or automatic cross-device sync in this version.</p></section><section class="card card-pad"><h2>Built around the play-by-play</h2><p>Points, lines, possessions, pass locations, outcomes, and defensive assignments live in one documented event format. Statistics are calculated separately, making it possible to connect another data source later.</p><button data-action="help">View stat definitions</button></section></div>`;}
function fieldSvg(p,events,g,interactive=false,highlightId=null,currentPossessionOnly=false){const f=g.field||FIELD,L=f.length,W=f.width,ez=f.endzone||20,dir=p?.direction||1;
 const possessionStart=currentPossessionOnly?events.findLastIndex(e=>e.type==='possession_start'):-1,draw=events.slice(possessionStart+1).filter(e=>e.type==='pass'&&e.from&&e.to),lastReception=[...draw].reverse().find(e=>['complete','goal'].includes(e.outcome)),last=events.filter(e=>e.type==='pass'||e.type==='possession_start').at(-1),pos=last?.to||last?.location;
 return `<svg class="pitch ${interactive?'':'locked'}" id="pitch" viewBox="-1 -1 ${L+2} ${W+2}" role="img" aria-label="Horizontal ultimate field, 110 by 40 yards. ${interactive?'Tap to record a location. Drag the latest reception to correct its location.':''}" style="aspect-ratio:${(L+2)/(W+2)}"><defs><pattern id="grass" width="10" height="${W}" patternUnits="userSpaceOnUse"><rect width="5" height="${W}" fill="#ffffff" opacity=".035"/></pattern><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="2" markerHeight="4" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z" fill="#f1efb5"/></marker></defs><rect width="${L}" height="${W}" fill="#557454"/><rect width="${ez}" height="${W}" fill="#456345"/><rect x="${L-ez}" width="${ez}" height="${W}" fill="#456345"/><rect width="${L}" height="${W}" fill="url(#grass)"/><g fill="none" stroke="#dfe6ca" stroke-width=".25"><rect width="${L}" height="${W}"/><path d="M${ez} 0v${W}M${L-ez} 0v${W}"/><path d="M${L/2} 0v${W}" stroke-dasharray="1.2 1.3" opacity=".6"/>${[ez+20,L-ez-20].map(x=>`<path d="M${x-1} ${W/2}h2m-1-1v2"/>`).join('')}</g><g fill="#d1ddbc" opacity=".35" font-family="sans-serif" font-size="2.2" letter-spacing=".8"><text x="${ez/2}" y="${W/2}" text-anchor="middle" transform="rotate(-90 ${ez/2} ${W/2})">${dir===1?'HOME END':'ATTACKING END'}</text><text x="${L-ez/2}" y="${W/2}" text-anchor="middle" transform="rotate(90 ${L-ez/2} ${W/2})">${dir===1?'ATTACKING END':'HOME END'}</text></g>${draw.map((e,i)=>`${interactive?'':`<line data-pass-hit="${esc(e.id)}" x1="${e.from.x}" y1="${e.from.y}" x2="${e.to.x}" y2="${e.to.y}" stroke="transparent" stroke-width="2.4" style="cursor:pointer"/>`}<line data-pass-line="${esc(e.id)}" x1="${e.from.x}" y1="${e.from.y}" x2="${e.to.x}" y2="${e.to.y}" stroke="${e.id===highlightId?'#ffffff':['complete','goal'].includes(e.outcome)?e.side==='us'?'#f1efb5':'#b6d8e1':'#efb183'}" stroke-width="${e.id===highlightId?'1.1':'.45'}" opacity="${e.id===highlightId?1:.4+.6*(i+1)/draw.length}" ${!['complete','goal'].includes(e.outcome)?'stroke-dasharray="1 1"':''} marker-end="url(#arrow)"/><circle ${interactive&&e.id===lastReception?.id?`class="draggable-reception" data-drag-reception="${esc(e.id)}"`:''} cx="${e.to.x}" cy="${e.to.y}" r="${e.id===highlightId?'.58':'.65'}" fill="${e.outcome==='goal'?'#e1ed8a':'#f1efb5'}"/>`).join('')}${pos?`<circle cx="${pos.x}" cy="${pos.y}" r="1.8" fill="#e2ec92" opacity=".24"/><circle cx="${pos.x}" cy="${pos.y}" r=".95" fill="#fbffd9" stroke="#2f4b2f" stroke-width=".35"/>`:''}</svg>`;}
function gamePage(){const g=game(),s=gameState(g),t=data.teams.find(t=>t.id===g.teamId),matchupGaps=tab==='stats'?matchupGapsFor(g):{},unknownPlayers=tab==='stats'&&highlightUnknown?unknownMatchupsFor(g,t):{};return `<div class="page-heading tracker-heading"><div class="scoreboard"><div class="club"><small>Your team</small>${esc(t.name)}</div><div class="score-block"><div class="big-score">${s.score[0]}<span>:</span>${s.score[1]}</div><button type="button" class="tournament-link" data-action="edit-tournament">${esc(g.tournament||'Tournament Unknown')}</button></div><div class="club"><small>Opponent</small>${esc(g.opponent)}</div></div><div class="actions"><span class="badge ${g.finished?'':'live'}">${g.finished?'Final':'Tracking live'}</span><button data-action="export-game">Export game</button>${!g.finished?'<button data-action="finish">Finish game</button>':'<button data-action="resume">Resume</button>'}<button class="danger" data-action="delete-game">Delete</button></div></div><div class="tabs">${[['track','Pitch tracker'],['plays','Play-by-play'],['stats','Game statistics']].map(([id,title])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${title}</button>`).join('')}</div>${g.importNotes?`<div class="notice">${g.importNotes.map(esc).join(' ')}</div>`:''}${tab==='stats'?`<div class="stats-settings card card-pad"><div><strong>oSE</strong><small>Offensive scoring efficiency: the EDGE cost of every turnover (throwaways, blocks, stalls and drops)</small></div><input id="ose-input" type="number" min="0" max="1" step="0.001" value="${gameOse(g,t).toFixed(3)}"><button class="primary" id="save-settings">Update calculations</button></div><div class="stats-team-row"><h2 class="stats-team-heading">${esc(t.name)}</h2><label class="inline-check outlier-toggle"><input id="highlight-unknown" type="checkbox" ${highlightUnknown?'checked':''}> Highlight unknown</label></div>${statsTable([g],[t],{advanced:true,breakdownTable:'us',matchupGaps,unknownPlayers})}<h2 class="stats-team-heading">${esc(g.opponent)}</h2>${statsTable([{...mirrorGame(g),settings:{...(g.settings||{}),ose:gameOse(g,t)}}],[{id:`${g.id}-opponent`,name:g.opponent,players:g.opponents}],{advanced:true,breakdownTable:'them',matchupGaps,unknownPlayers})}<p class="stats-help">Opponent rows are derived from the same events. Opponent blocks are only credited when a block turnover names the defender, and the opponent’s oSE reuses this game’s oSE setting.</p>`:tab==='plays'?reviewPage(g):trackerPage(g,s,t)}`;}
function trackerPage(g,s,t){const p=s.point,events=p?.events||[],live=s.active&&!g.finished,label=s.side==='us'?t.name:g.opponent,arrow=(p?.direction||1)===1?'━━━━━━━━▶':'◀━━━━━━━━',latest=events.filter(e=>e.type!=='point_end').at(-1);return `<div class="tracking-layout"><section class="card pitch-card tracker-focus"><div class="pitch-toolbar"><div class="actions"><strong>POINT ${s.points.length||1}</strong>${p?`<span class="badge">${p.starting}</span>`:''}<span class="badge ${live?'live':''}">${g.finished?'Complete':!s.active?'Between points':s.side==='us'?'Our disc':'Opponent disc'}</span></div>${live?`<div class="force-picker" aria-label="Defensive force"><span>${esc(other(s.side)==='us'?t.name:g.opponent)} force</span>${FORCES.map(force=>`<button data-force="${force}" class="${s.forces[other(s.side)]===force?'selected':''}">${force[0].toUpperCase()+force.slice(1)}</button>`).join('')}</div>`:''}<div class="actions">${live?'<button data-action="substitute" title="Change a player on the line">⇄ Substitute</button><button data-action="unattributed-goal" title="Record a goal not credited to any player">Goal</button><button data-action="unattributed-turnover" title="Record a turnover not credited to any player">Turnover</button><button data-action="undo" title="Undo last event">↶ Undo</button>':!g.finished?'<button class="primary" data-action="point">Next point</button>':''}</div></div><div class="pitch-wrap"><div class="attack-strip"><span>${arrow}</span> OUR ATTACK <span>${arrow}</span></div>${fieldSvg(p,events,g,live,null,true)}<div class="attack-strip bottom"><span>${arrow}</span> OUR ATTACK <span>${arrow}</span></div><div class="field-resize" role="separator" aria-orientation="horizontal" aria-label="Resize the field" title="Drag to resize the field"></div></div><div class="pitch-instruction"><p>${g.finished?'Game complete.':!s.active?'Choose the players for the next point.':s.needsPickup?`Tap where ${esc(label)} takes possession.${p&&!p.events.some(e=>e.type==='possession_start')?' For an out-of-bounds pull, tap the brick mark (+).':''}`:`${!s.holder&&s.marker&&!isPlaceholderMatchup(s.marker)?`<strong>Unknown</strong> has the disc, marked by <strong>${esc(playerName(s.marker))}</strong>`:`<strong>${esc(playerName(s.holder))}</strong> has the disc`} · tap the destination, then the receiver.`}</p><small>${latest?esc(feedSummary(latest,g)):'Tap the field to begin.'}</small></div></section></div>`;}
function feedSummary(e,g){if(e.type==='possession_start')return `${playerName(e.playerId,g)} took possession`;if(e.type==='unattributed_goal')return 'Goal · unattributed';if(e.type==='pass')return `${playerName(e.throwerId,g)} → ${playerName(e.receiverId,g)} · ${e.handBlock?'hand block':e.outcome}`;if(e.type==='turnover')return e.reason.replaceAll('_',' ');if(e.type==='substitution')return `${playerName(e.outId,g)} → ${playerName(e.inId,g)} · substitution`;if(e.type==='force')return `${e.side==='us'?team().name:g.opponent} force ${e.force}`;return 'Point recorded';}
function feedRow(e,p,g,i){let title='',titleHtml='',detail='',distance='';if(e.type==='possession_start'){title=`${playerName(e.playerId,g)} takes possession`;detail=e.side==='us'?'Our possession':'Opponent possession';const pickupMarker=e.markerId||e.opponentMarkerId;if(e.pullerId){const pull=pullMetrics(e,p,g.field);detail+=` · pulled by ${playerName(e.pullerId,g)}${pull.outOfBounds?' · out of bounds':` · ${pull.vertical.toFixed(1)} yd deep`}`;}if(pickupMarker)detail+=` · marker: ${playerName(pickupMarker,g)}`;}else if(e.type==='unattributed_goal'){title='Goal · unattributed';detail='Not credited to any player';}else if(e.type==='pass'){titleHtml=`${esc(playerName(e.throwerId,g))} → <button class="receiver-hold" data-receiver-edit="${esc(e.id)}" title="Click to change receiver">${esc(playerName(e.receiverId,g))}</button>`;detail=e.handBlock?'Hand block':({complete:'Completed pass',goal:'Goal · assist',drop:'Drop',throwaway:'Throwaway',block:'Block',stall:'Stall out'})[e.outcome];if(e.outcome==='block'&&e.blockerId)detail+=` by ${playerName(e.blockerId,g)}`;if(e.side==='them')detail+=' · opponent';if(e.force)detail+=` · ${e.force} force${e.break?' · break':''}`;const markerId=e.markerId||e.opponentMarkerId,receiverDefenderId=e.receiverDefenderId||e.opponentReceiverDefenderId;if(markerId)detail+=` · marker: ${playerName(markerId,g)}`;if(receiverDefenderId)detail+=` · receiver defender: ${playerName(receiverDefenderId,g)}`;const m=passMetrics(e,p);distance=`${m.distance.toFixed(1)} yd · ${m.gain>=0?'+':''}${m.gain.toFixed(1)} gain`;}else if(e.type==='turnover'){title=e.reason==='block'?`${playerName(e.blockerId,g)} · block`:'Turnover';detail=e.reason.replaceAll('_',' ');}else if(e.type==='substitution'){title=`${playerName(e.outId,g)} → ${playerName(e.inId,g)}`;detail='Substitution';}else if(e.type==='force'){title=`${e.side==='us'?team().name:g.opponent} force ${e.force}`;detail='Force change';}else{title=e.winner==='us'?'Our point':'Opponent point';detail='Point result';}return `<div class="feed-row ${e.id===highlightedPassId?'highlighted':''}" ${e.type==='pass'?`data-highlight-pass="${esc(e.id)}"`:''}><span class="event-no">${String(i+1).padStart(2,'0')}</span><span class="event-icon">${e.outcome==='goal'||e.type==='unattributed_goal'?'★':e.type==='possession_start'?'○':e.type==='substitution'?'⇄':e.type==='force'?'◐':'↗'}</span><div class="event-copy">${titleHtml||esc(title)}<small>${esc(detail)}</small></div><span class="distance">${distance}</span>${e.type==='pass'?`<button data-edit="${esc(e.id)}" aria-label="Correct pass">Edit</button>`:''}${e.type==='force'?`<button data-delete-force="${esc(e.id)}" aria-label="Delete force change">Delete</button>`:''}${e.type==='substitution'?`<button data-delete-substitution="${esc(e.id)}" aria-label="Delete substitution">Delete</button>`:''}${e.type==='possession_start'?`<button data-edit-possession="${esc(e.id)}" aria-label="Correct possession start">Edit</button>`:''}</div>`;}
function reviewPage(g){const points=pointsOf(g);const p=points.find(p=>p.id===reviewPoint)||(g.finished?points[0]:points.at(-1));if(!p)return '<div class="card empty"><h2>No plays yet</h2><p>Start a point on the pitch tracker.</p></div>';reviewPoint=p.id;const es=p.events.filter(e=>e.type!=='point_end'),possessions=possessionSummary(es,g),expanded=reviewSummary&&reviewPossession?.pointId===p.id?possessions[reviewPossession.index]:null,expandedIds=new Set(expanded?.eventIds||[]),indexed=es.map((e,index)=>({e,index})),shown=expanded?indexed.filter(({e})=>expandedIds.has(e.id)):indexed,limit=es.length;return `<div class="review-controls"><label for="review-point">Review</label><select id="review-point">${points.map((x,i)=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${pointScoreLabel(points,i)} · Point ${i+1} · ${x.starting} · ${x.winner==='us'?'Scored':x.winner==='them'?'Conceded':'In progress'}</option>`).join('')}</select><button id="toggle-summary" class="${reviewSummary?'selected':''}" aria-pressed="${reviewSummary}">${reviewSummary?'Full log':'Summary view'}</button><button data-action="insert-point">＋ Insert point</button>${p.inserted?`<button data-add-play="${esc(p.id)}">＋ Add play</button>`:''}<button data-action="undo">↶ Undo latest event</button></div><section class="card pitch-card review-pitch"><div class="pitch-wrap">${fieldSvg(p,shown.map(({e})=>e),g,false,highlightedPassId)}<div class="pitch-legend"><span>${expanded?`One possession · ${shown.length} of ${es.length} events`:`Play ${limit} of ${es.length}`}</span><span>Click a pass below to highlight it</span></div><div class="field-resize" role="separator" aria-orientation="horizontal" aria-label="Resize the field" title="Drag to resize the field"></div></div></section><div class="play-feed">${reviewSummary?possessions.map((possession,index)=>summaryRow(possession,index,possession===expanded)+(possession===expanded?shown.map(({e,index})=>feedRow(e,p,g,index)).join(''):'')).join(''):pointForceRow(g,p)+indexed.map(({e,index})=>feedRow(e,p,g,index)).join('')}</div>`;}
