 if($('#save-settings'))$('#save-settings').onclick=async()=>{const restore=captureTableScroll(),g=game();g.settings={...(g.settings||{}),ose:Number($('#ose-input').value)};await commit();restore();toast('Game statistics updated.');};
 if($('#save-secondary-settings'))$('#save-secondary-settings').onclick=async()=>{const restore=captureTableScroll();data.settings={...(data.settings||{}),secondaryPreviousShare:Number($('#secondary-prev').value),secondaryPreviousPreviousShare:Number($('#secondary-prev2').value),includeSecondaryInTotal:$('#include-secondary-total').checked};huckYards=Math.max(0,Number($('#stats-huck-yards').value)||0);await persist();render();restore();toast('Player Stats calculations updated.');};
