 const pairedDefender=offenseId=>{if(!offenseId)return null;const pair=pairings.find(item=>item.includes(offenseId)&&item.some(id=>id!==offenseId&&defenderButtons().some(button=>button.getAttribute(defenderAttribute)===id)));return pair?pair.find(id=>id!==offenseId):null;};
