function editPass(id){const g=game(),e=g.events.find(e=>e.id===id),p=pointsOf(g).find(p=>p.events.some(e=>e.id===id)),line=team().players.filter(x=>pointParticipants(g,p,'us').includes(x.id)),ps=e.side==='us'?team().players:g.opponents,markerValue=e.side==='them'?e.markerId:e.opponentMarkerId,defenderValue=e.side==='them'?e.receiverDefenderId:e.opponentReceiverDefenderId,defenders=e.side==='them'?line:g.opponents.filter(x=>pointParticipants(g,p,'them').includes(x.id)||x.id===markerValue||x.id===defenderValue);modal('Correct pass details',`<form id="edit-form"><p>Correct the outcome, players, defensive assignments, or coordinates. An outcome that changes who has the disc next (catch, goal or turnover) can only be changed on the latest event.</p><div class="form-grid"><div><label class="field" for="edit-outcome">Outcome</label><select id="edit-outcome">${PASS_OUTCOMES.map(([value,label])=>`<option value="${value}" ${passOutcomeValue(e)===value?'selected':''}>${label}</option>`).join('')}</select></div><div id="edit-blocker-field"><label class="field" for="edit-blocker">Block credited to</label><select id="edit-blocker">${options(defenders,e.blockerId)}</select></div></div><div class="form-grid"><div><label class="field" for="edit-thrower">Thrower</label><select id="edit-thrower">${options(ps,e.throwerId)}</select></div><div><label class="field" for="edit-receiver">Receiver / target</label><select id="edit-receiver">${options(ps,e.receiverId)}</select></div></div><div class="form-grid">${[['from-x','Start X',e.from.x,g.field.length],['from-y','Start Y',e.from.y,g.field.width],['to-x','End X',e.to.x,g.field.length],['to-y','End Y',e.to.y,g.field.width]].map(([id,label,val,max])=>`<div><label class="field" for="${id}">${label} (yd)</label><input type="number" step="any" min="0" max="${max}" id="${id}" value="${val}" required></div>`).join('')}</div><div class="form-grid"><div><label class="field" for="edit-marker">Marker</label><select id="edit-marker">${options(defenders,markerValue,true,true)}</select></div><div><label class="field" for="edit-defender">Receiver’s defender</label><select id="edit-defender">${options(defenders,defenderValue,true,true)}</select></div></div><label class="field" for="edit-force">Force</label><select id="edit-force"><option value="">Not recorded</option>${FORCES.map(force=>`<option value="${force}" ${e.force===force?'selected':''}>${force[0].toUpperCase()+force.slice(1)}</option>`).join('')}</select><p>Edits apply to this pass only. Check adjacent plays if the disc holder or location changed.</p><div class="modal-foot"><button type="button" data-cancel>Cancel</button><button type="submit" class="primary">Save correction</button></div></form>`);$('#edit-form').onsubmit=async ev=>{ev.preventDefault();const chosenOutcome=$('#edit-outcome').value,newOutcome=chosenOutcome==='hand_block'?'block':chosenOutcome;if(possessionResult(newOutcome)!==possessionResult(e.outcome)&&g.events.at(-1)!==e){toast('That outcome changes who has the disc next. Undo back to this play to change it.');return;}g.revisions??=[];g.revisions.push({at:new Date().toISOString(),action:'edit',event:structuredClone(e)});e.throwerId=$('#edit-thrower').value||null;e.receiverId=$('#edit-receiver').value||null;e.from={x:Number($('#from-x').value),y:Number($('#from-y').value)};e.to={x:Number($('#to-x').value),y:Number($('#to-y').value)};e.force=$('#edit-force').value||null;e.break=isBreak(e,p,g.field);const previousDefender=defenderValue;if(e.side==='them'){e.markerId=$('#edit-marker').value||null;e.receiverDefenderId=$('#edit-defender').value||null;}else{e.opponentMarkerId=$('#edit-marker').value||null;e.opponentReceiverDefenderId=$('#edit-defender').value||null;}e.outcome=newOutcome;if(chosenOutcome==='hand_block')e.handBlock=true;else delete e.handBlock;e.blockerId=newOutcome==='block'?$('#edit-blocker').value||null:null;if(newOutcome==='stall'){e.receiverId=null;e.to={...e.from};}e.break=isBreak(e,p,g.field);fillNextMarker(g,e,previousDefender);closeModal();await commit();};const showBlocker=()=>{$('#edit-blocker-field').hidden=!['block','hand_block'].includes($('#edit-outcome').value);};$('#edit-outcome').onchange=()=>{showBlocker();if(['block','hand_block'].includes($('#edit-outcome').value))$('#edit-blocker').value=$($('#edit-outcome').value==='hand_block'?'#edit-marker':'#edit-defender').value;};showBlocker();}
function download(content,label){const blob=new Blob([JSON.stringify({...content,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`right-trousers-${label}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('JSON export created.');}
function exportGame(){const g=game();download({...emptyData(),teams:[team()],games:[g],sources:data.sources.filter(s=>s.id===g.source?.id)},'game');}
async function importFile(file){if(!file)return;if(file.size>50000000){toast('Choose a file smaller than 50 MB.');return;}try{toast('Reading your game file…');const buf=await file.arrayBuffer(),sig=new Uint8Array(buf);let incoming;if(sig[0]===80&&sig[1]===75)incoming=convertStatto(await readStattoZip(buf));else{const raw=JSON.parse(new TextDecoder().decode(buf));incoming=raw.format==='fieldbook'?validateData({...raw,format:'righttrousers'}):raw.format==='righttrousers'?validateData(raw):convertStatto(raw);}const result=mergeData(data,incoming);modal('Ready to import',`<p><strong>${incoming.teams.length} teams</strong> · <strong>${result.added} new games</strong> · ${result.skipped} existing games will be kept.</p>${incoming.sources.length?'<div class="notice">Statto source records are preserved. Historical field coordinates are interpreted as normalized portrait coordinates on a 110 × 40 yd field; original pitch types are retained. Defender yardage is unavailable for historical games.</div>':''}<p>This merges into your library on this device. Your existing games will not be overwritten.</p><div class="modal-foot"><button data-cancel>Cancel</button><button class="primary" id="confirm-import">Import games</button></div>`);$('#confirm-import').onclick=async()=>{data=result.data;view='games';gameId=null;teamId=incoming.teams[0]?.id||null;closeModal();await commit();toast(`Imported ${result.added} games. ${result.skipped} existing games kept.`);};}catch(e){toast('Import failed: '+e.message);}}
function finish(){const g=game();g.finished=true;commit();}
function deleteGame(){const g=game();modal('Delete this game?',`<p>This permanently removes ${esc(team()?.name||'your team')} vs ${esc(g.opponent)} and its play-by-play from this device. Export it first if you may need it later.</p><div class="modal-foot"><button data-cancel>Keep game</button><button class="danger" id="confirm-delete-game">Delete game</button></div>`);$('#confirm-delete-game').onclick=async()=>{data.games=data.games.filter(item=>item.id!==g.id);gameId=null;view='games';closeModal();await persist();render();toast('Game deleted.');};}
function help(){modal('A field guide',`<ol class="help-list"><li>Create a team and add at least seven players.</li><li>Start a game and choose the line, starting O/D, and attacking direction.</li><li>Tap the disc’s initial location and select the holder.</li><li>Tap each throw’s destination, choose its target and outcome. A completed pass keeps possession; a turnover prompts a new pickup.</li><li>Use Substitute during a live point to update the active line. Everyone who appears receives credit for the point played.</li><li>On defense, optionally select the marker and receiver’s defender. The latter becomes the next marker.</li><li>After a goal, select the next line. O/D and direction default from the previous point.</li></ol><h3>Stat definitions</h3><p>Possessions initiated credit the first player controlling the disc after a pull or turnover. Goals credit the scorer, assists credit the final thrower, and secondary assists credit the thrower of the preceding completed pass in that possession.</p><p>Distance is straight-line distance between throw and catch. Gain is signed forward progress. Only completed throws count toward yardage. An offensive opportunity counts once for every player who appears on the line if the team starts on O or the opponent turns over.</p><p>A drop credits a drop to the intended receiver; throwaways and blocked throws count as thrower turnovers. On opponent throws, the marker is charged throwing yardage/assists allowed, the receiver defender is charged receiving yardage/goals allowed and target attempts. A throwaway credits the marker with a forced throwaway.</p><p>Unknown or unassigned defenders receive no individual credit.</p><div class="modal-foot"><button data-cancel class="primary">Got it</button></div>`);}
async function recordUnattributedGoal(){const g=game(),s=gameState(g);g.events.push(event('unattributed_goal',{side:s.side,location:s.location}));closeModal();await commit();toast(`${s.side==='us'?'Your team':'Opponent'} scores. Choose the next line.`);selectLine();}
function unattributedGoal(){const g=game(),s=gameState(g);if(!s.active||g.finished)return;if(g.skipUnattributedGoalConfirm){recordUnattributedGoal();return;}modal('Record goal?',`<p>This goal will not be attributed to any player. No scorer or assist is credited.</p><label class="check"><input type="checkbox" id="skip-goal-confirm"> Don’t show this again for this game</label><div class="modal-foot"><button data-cancel>Cancel</button><button class="primary" id="confirm-goal">Record goal</button></div>`);$('#confirm-goal').onclick=()=>{if($('#skip-goal-confirm').checked)g.skipUnattributedGoalConfirm=true;recordUnattributedGoal();};}
async function unattributedTurnover(){const g=game(),s=gameState(g);if(!s.active||g.finished)return;g.events.push(event('turnover',{side:s.side,reason:'unattributed',location:s.location}));await commit();}
const actions={'toggle-sidebar':toggleSidebar,'unattributed-goal':unattributedGoal,'unattributed-turnover':unattributedTurnover,'insert-point':insertPoint,'new-team':newTeam,'new-game':newGame,'select-games':selectGames,'show-heatmap':showHeatmap,'rate-trends':rateTrends,'huck-chart':huckChart,point:selectLine,opponents:opponentRoster,substitute,undo,finish,'delete-game':deleteGame,'edit-tournament':editTournament,resume:()=>{game().finished=false;commit();},import:()=>$('#import-file').click(),export:()=>download(data,'library'),'export-game':exportGame,help};
$('#import-file').onchange=e=>{importFile(e.target.files[0]);e.target.value='';};
try{data=await readStore()||emptyData();validateData(data);}catch(e){saveLabel='Storage unavailable';toast('Could not read local storage. Import a JSON backup if needed.');}
if(!data.teams.length){try{const r=await fetch('./initial-data.json');if(r.ok){data=validateData(await r.json());await persist();}}catch{}}
{const pending=data.games.filter(game=>game.unguardedApplied!==UNGUARDED_VERSION).length,changed=data.games.map(game=>[applyUnguarded(game),recomputeBreaks(game)].some(Boolean)).some(Boolean);if(pending||changed)await persist();}
render();
let matchedTooltipTarget=null,matchedTooltipElement=null;
function hideMatchedTooltip(){matchedTooltipElement?.remove();matchedTooltipElement=null;matchedTooltipTarget=null;}
function showMatchedTooltip(target){const message=target?.getAttribute('data-matched-tooltip');if(!message)return;hideMatchedTooltip();matchedTooltipTarget=target;matchedTooltipElement=document.createElement('div');matchedTooltipElement.className='matched-hover-tooltip';matchedTooltipElement.textContent=message;(target.closest('dialog')||document.body).append(matchedTooltipElement);const rect=target.getBoundingClientRect(),tip=matchedTooltipElement.getBoundingClientRect(),left=Math.max(8,Math.min(innerWidth-tip.width-8,rect.left+(rect.width-tip.width)/2)),top=rect.bottom+tip.height+8<=innerHeight?rect.bottom+5:Math.max(8,rect.top-tip.height-5);matchedTooltipElement.style.left=`${left}px`;matchedTooltipElement.style.top=`${top}px`;requestAnimationFrame(()=>matchedTooltipElement?.classList.add('visible'));}
document.addEventListener('pointerover',e=>{const target=e.target.closest?.('[data-matched-tooltip]');if(target&&target!==matchedTooltipTarget)showMatchedTooltip(target);});
document.addEventListener('pointerout',e=>{const target=e.target.closest?.('[data-matched-tooltip]');if(target&&target===matchedTooltipTarget&&!target.contains(e.relatedTarget))hideMatchedTooltip();});
document.addEventListener('focusin',e=>{const target=e.target.closest?.('[data-matched-tooltip]');if(target)showMatchedTooltip(target);});
document.addEventListener('focusout',e=>{const target=e.target.closest?.('[data-matched-tooltip]');if(target===matchedTooltipTarget)hideMatchedTooltip();});
document.addEventListener('scroll',hideMatchedTooltip,true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&view==='game'&&!$('#modal').open){gameId=null;view='games';render();}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
